import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"AB#6447 — CAF/WAF coverage audit","description":"","frontmatter":{},"headers":[],"relativePath":"audits/AB6447-caf-waf-coverage-audit.md","filePath":"audits/AB6447-caf-waf-coverage-audit.md"}'),r={name:"audits/AB6447-caf-waf-coverage-audit.md"};function i(d,e,n,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="ab-6447-—-caf-waf-coverage-audit" tabindex="-1">AB#6447 — CAF/WAF coverage audit <a class="header-anchor" href="#ab-6447-—-caf-waf-coverage-audit" aria-label="Permalink to &quot;AB#6447 — CAF/WAF coverage audit&quot;">​</a></h1><p><strong>Scope:</strong> Does Azure Scout actually assess against the Cloud Adoption Framework and the Well-Architected Framework, or does it sample them? <strong>Method:</strong> Every rule file in <code>src/assess/rules/</code> read and catalogued, then matched against the current (July 2026) Microsoft-published WAF design-review checklists and CAF landing zone design areas retrieved from Microsoft Learn. <strong>Date:</strong> 2026-07-30 <strong>Status:</strong> read-only audit — no code changed.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p><strong>No. Scout does not fully assess against CAF/WAF, and the gap is much larger than the rule count suggests.</strong></p><table tabindex="0"><thead><tr><th>Framework</th><th>Official scope</th><th>Scout&#39;s rules</th><th>Meaningful coverage</th></tr></thead><tbody><tr><td><strong>WAF</strong> — 5 pillars</td><td><strong>59</strong> design-review checklist items (RE 10, SE 12, CO 14, OE 11, PE 12)</td><td>33 rules in <code>waf.*</code> (+ borrowed <code>caf.*</code>)</td><td><strong>~8 items solidly covered, ~18 partial, ~33 untouched → ~14% solid / ~44% touched</strong></td></tr><tr><td><strong>CAF</strong> — 8 landing zone design areas</td><td><strong>~316 design considerations + ~394 design recommendations</strong> across ~43 pages</td><td>53 rules across the 8 <code>caf.*</code> design-area files</td><td><strong>~10%</strong></td></tr></tbody></table><p>Three findings dominate:</p><ol><li><p><strong>A shipped defect means operators only ever see one assessment.</strong> The wizard&#39;s path to the assessment manifest is wrong by two directory levels, so <code>Test-Path</code> fails silently and it falls back to a hardcoded <code>@(&#39;LandingZone&#39;)</code>. 21 of 22 registered assessments are unreachable from the wizard. Confirmed empirically, root cause identified, one-line fix. <strong>This is the highest-priority item in this audit.</strong> See <a href="#the-wizard-defect">The wizard defect</a>.</p></li><li><p><strong>32% of all rules (47 of 148) are <code>manual: true</code></strong> — they have <code>query: null</code>, assert nothing, and produce no automated verdict. They are prompts for a human. Several sit on top of data Scout <em>already collects</em>. Whole areas are manual-only: <code>waf.storage.yaml</code> is 4 of 5 manual, <code>waf.reliability.yaml</code> is 1 of 3.</p></li><li><p><strong>Scout collects Azure Policy compliance state and never scores it.</strong> <code>Get-ScoutSubscriptionSecurityPolicySweep.ps1</code> pulls <code>PolicyComplianceStates</code>, <code>Start-ScoutPolicyJob.ps1</code> computes <code>nonCompliantResources</code> / <code>nonCompliantPolicies</code>, and <code>Get-ScoutApiResources.ps1</code> calls the <code>policyStates/latest/summarize</code> API. <strong>Zero rules reference any of it.</strong> <code>caf.governance.yaml</code> checks that policy assignments <em>exist</em> and that there are <em>more than five</em> — the single most valuable governance signal in Azure is collected, paid for in query time, and thrown away.</p></li></ol><p>The rule corpus is real work and the automated rules that exist are mostly sound. The problem is not quality-per-rule, it is <strong>breadth</strong>: Scout covers the parts of CAF/WAF that are trivially observable from Azure Resource Graph, and skips almost everything else. The owner&#39;s instinct is correct on both counts — there should be more assessments, and the existing ones do not fully cover their pillars.</p><hr><h2 id="the-wizard-defect" tabindex="-1">The wizard defect <a class="header-anchor" href="#the-wizard-defect" aria-label="Permalink to &quot;The wizard defect&quot;">​</a></h2><p><strong>Confirmed. This is a real, shipped, user-visible defect.</strong></p><h3 id="what-s-wrong" tabindex="-1">What&#39;s wrong <a class="header-anchor" href="#what-s-wrong" aria-label="Permalink to &quot;What&#39;s wrong&quot;">​</a></h3><p><code>src/Start-AZSCWizard.ps1:238</code>:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$manifestPath </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Split-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Split-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Split-Path</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $PSScriptRoot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Parent) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Parent) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Parent) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;manifests/assessments.psd1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$assessmentNames </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> @</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;LandingZone&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Test-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $manifestPath) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { $assessmentNames </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> @</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Import-PowerShellDataFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $manifestPath).Keys </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Sort-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    catch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Write-Verbose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>Start-AZSCWizard.ps1</code> lives in <code>src/</code>, so <code>$PSScriptRoot</code> is <code>&lt;repo&gt;/src</code>. Three <code>Split-Path -Parent</code> calls climb three levels from there. Resolved empirically:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RESOLVES TO: D:\\git\\manifests\\assessments.psd1</span></span>
<span class="line"><span>EXISTS: False</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The manifest is at <code>&lt;repo&gt;/manifests/assessments.psd1</code> — <strong>one</strong> level up, not three. <code>Test-Path</code> returns <code>$false</code>, the <code>if</code> never runs, and <code>$assessmentNames</code> stays at its hardcoded fallback. The operator is offered a one-item checklist containing only <code>LandingZone</code>.</p><p>Note the failure is <strong>silent by design in the wrong place</strong>: the <code>catch</code> writes a <code>Write-Verbose</code> explaining the fallback, but that catch never fires. The <code>Test-Path</code> guard swallows the real failure with no message at all. Nothing is logged even at <code>-Verbose</code>.</p><h3 id="root-cause" tabindex="-1">Root cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root cause&quot;">​</a></h3><p><code>archived/Modules/Public/PublicFunctions/Start-AZSCWizard.ps1:199</code> has the <strong>identical</strong> expression. In the original ARI-fork layout the file sat at <code>Modules/Public/PublicFunctions/</code>, where three parents correctly resolved to the repo root. The engine rewrite moved the file to <code>src/</code> and the path arithmetic was never updated. The correct sibling pattern is already used elsewhere — <code>src/Invoke-ScoutAssessmentCore.ps1:95</code>:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$manifest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Import-PowerShellDataFile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$PSScriptRoot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/../manifests/assessments.psd1&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="why-it-shipped" tabindex="-1">Why it shipped <a class="header-anchor" href="#why-it-shipped" aria-label="Permalink to &quot;Why it shipped&quot;">​</a></h3><p><strong>There is no wizard test.</strong> <code>ls tests/ | grep -i wizard</code> returns nothing, and no test anywhere references <code>manifestPath</code> or the <code>&#39;Assessments to run&#39;</code> prompt. The manifest-discovery path has never been exercised.</p><h3 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to &quot;Impact&quot;">​</a></h3><ul><li>21 of 22 registered assessments are unreachable via the wizard — including every per-pillar and per-domain assessment the owner is asking about. From the operator&#39;s seat, Scout looks like a one-assessment tool.</li><li>The defect is invisible: no error, no warning, no verbose output. It reads as a deliberate product decision.</li><li><code>Invoke-AzureScout -Assessment &lt;name&gt;</code> is unaffected — the direct path works. So the feature exists and is correct; only the discovery surface is broken. Anyone reading the docs is fine; anyone using the guided experience the wizard exists to provide is not.</li></ul><h3 id="fix" tabindex="-1">Fix <a class="header-anchor" href="#fix" aria-label="Permalink to &quot;Fix&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$manifestPath </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Split-Path</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $PSScriptRoot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Parent) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;manifests/assessments.psd1&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Plus three things that should land with it:</p><ol><li>Replace the silent <code>Test-Path</code> guard with a visible warning when the manifest can&#39;t be read, so the next path regression is loud.</li><li>Add a Pester test asserting the wizard resolves the real manifest and returns all 22 names.</li><li>Reconsider <code>-DefaultSelected @(&#39;LandingZone&#39;)</code> on line 244. Even once fixed, only LandingZone is pre-checked. That is defensible (LandingZone is the <code>caf.* + waf.*</code> roll-up and running all 22 duplicates work), but it should be a deliberate documented choice, not an accident of the fallback value.</li></ol><p><strong>Secondary issue on the same line:</strong> <code>.Keys | Sort-Object</code> produces alphabetical order — <code>AI, Analytics, Compute, Containers, ...</code> — which buries <code>LandingZone</code> mid-list and gives no signal that the 22 entries are three different kinds of thing (roll-ups, per-category, sub-bundles). The manifest&#39;s own comment structure groups them; the wizard discards that grouping.</p><hr><h2 id="waf-coverage-matrix" tabindex="-1">WAF coverage matrix <a class="header-anchor" href="#waf-coverage-matrix" aria-label="Permalink to &quot;WAF coverage matrix&quot;">​</a></h2><p>Official source: the five per-pillar design review checklists on Microsoft Learn, current July 2026. <strong>59 items total.</strong></p><p>Legend: <strong>Solid</strong> = automated rule that genuinely tests the item. <strong>Partial</strong> = touches one narrow aspect, or is manual-only. <strong>None</strong> = no rule.</p><h3 id="reliability-—-3-rules-against-10-checklist-items" tabindex="-1">Reliability — 3 rules against 10 checklist items <a class="header-anchor" href="#reliability-—-3-rules-against-10-checklist-items" aria-label="Permalink to &quot;Reliability — 3 rules against 10 checklist items&quot;">​</a></h3><p><code>src/assess/rules/waf.reliability.yaml</code> — the thinnest file in the repo, and it is the pillar most customers care about.</p><table tabindex="0"><thead><tr><th>Item</th><th>Scout</th><th>Verdict</th></tr></thead><tbody><tr><td>RE:01 Simplify design</td><td>—</td><td>None</td></tr><tr><td>RE:02 Identify and rate flows</td><td>—</td><td>None</td></tr><tr><td>RE:03 Failure mode analysis</td><td><code>WAF-RE-03</code> (<code>manual: true</code>)</td><td>Partial</td></tr><tr><td>RE:04 Reliability/recovery targets</td><td>—</td><td>None</td></tr><tr><td>RE:05 Redundancy</td><td><code>WAF-RE-05</code> zone-redundant VMs; <code>WAF-STO-01</code> storage SKU</td><td><strong>Solid</strong> (VM/storage only)</td></tr><tr><td>RE:06 Scaling strategy</td><td>—</td><td>None (<code>WAF-PE-04</code> autoscale sits in Performance)</td></tr><tr><td>RE:07 Self-preservation / self-healing</td><td>—</td><td>None</td></tr><tr><td>RE:08 Chaos / resiliency testing</td><td>—</td><td>None</td></tr><tr><td>RE:09 Disaster recovery plans</td><td><code>WAF-RE-09</code> &quot;Backup configured&quot;</td><td>Partial — <strong>mislabelled</strong></td></tr><tr><td>RE:10 Health monitoring</td><td>—</td><td>None (<code>WAF-OE-01</code> diagnostics sits in OpEx)</td></tr></tbody></table><p><strong>Coverage: 1 solid, 2 partial, 7 none ≈ 10–25%.</strong></p><p><code>WAF-RE-09</code> deserves calling out. RE:09 is <em>&quot;implement structured, tested, documented DR plans&quot;</em>. The rule asserts <code>$.management.recoveryVaults[*].backupItems[*]</code> count &gt; 0 — <strong>one backup item anywhere in the tenant passes the entire DR checklist item</strong>. Backup is not DR. There is no ASR check, no RTO/RPO check, no region-pair check, no failover-test check, despite CAF&#39;s Management design area specifying all of them.</p><p>Also absent: RE:05 only covers VMs and storage accounts. Zone redundancy for SQL, AKS, App Service, gateways, Event Hub, and APIM is checked — but in <code>caf.databases</code>, <code>caf.containers</code>, <code>caf.integration</code>. The Reliability pillar doesn&#39;t see them, so a Reliability-scoped run scores against 3 rules while the evidence for 6 more sits in adjacent files. <strong>This is the single clearest argument for restructuring the rule namespace</strong> (see <a href="#recommendation-1-restructure-the-rule-namespace-around-the-two-real-axes">Recommendations</a>).</p><h3 id="security-—-strongest-pillar-8-of-12-touched" tabindex="-1">Security — strongest pillar, ~8 of 12 touched <a class="header-anchor" href="#security-—-strongest-pillar-8-of-12-touched" aria-label="Permalink to &quot;Security — strongest pillar, ~8 of 12 touched&quot;">​</a></h3><p><code>waf.security.yaml</code> (7) + <code>caf.security.yaml</code> (7) + <code>caf.identity.yaml</code> (7) + service-domain rules.</p><table tabindex="0"><thead><tr><th>Item</th><th>Scout</th><th>Verdict</th></tr></thead><tbody><tr><td>SE:01 Security baseline</td><td><code>CAF-SEC-02</code> Defender enabled; <code>WAF-SE-02/04</code> Advisor; <code>CAF-SEC-07</code> secure score (manual)</td><td>Partial</td></tr><tr><td>SE:02 Secure development lifecycle</td><td>—</td><td>None</td></tr><tr><td>SE:03 Data classification</td><td><code>CAF-ANL-02</code> Purview (manual)</td><td>Partial</td></tr><tr><td>SE:04 Segmentation</td><td><code>CAF-NET-01</code> hub-spoke; <code>CAF-SEC-01</code> NSG</td><td>Partial</td></tr><tr><td>SE:05 Identity and access</td><td><code>CAF-IDN-01…07</code></td><td><strong>Solid</strong></td></tr><tr><td>SE:06 Network traffic control</td><td><code>WAF-SE-01/03</code>, <code>CAF-SEC-01</code>, <code>CAF-NET-02/04/07</code></td><td><strong>Solid</strong></td></tr><tr><td>SE:07 Encryption</td><td><code>WAF-SE-05</code>, <code>CAF-DB-03</code> TDE, <code>CAF-AI-05</code> CMK, <code>CAF-STO-02/03</code></td><td><strong>Solid</strong></td></tr><tr><td>SE:08 Harden resources</td><td>TLS/HTTPS/public-access rules across storage, web, DB, AI, IoT, containers</td><td><strong>Solid</strong></td></tr><tr><td>SE:09 Application secrets</td><td><code>WAF-SE-07</code>, <code>CAF-SEC-04/05</code> KV soft-delete + purge protection</td><td>Partial</td></tr><tr><td>SE:10 Monitor threats</td><td><code>WAF-SE-06</code>, <code>CAF-SEC-02</code>, <code>CAF-DB-04</code></td><td><strong>Solid</strong></td></tr><tr><td>SE:11 Security testing</td><td>—</td><td>None</td></tr><tr><td>SE:12 Incident response</td><td>—</td><td>None</td></tr></tbody></table><p><strong>Coverage: 5 solid, 4 partial, 3 none ≈ 45–60%.</strong> Genuinely respectable.</p><p>Gaps worth fixing, all observable from data Scout already has or can cheaply get: Key Vault using <strong>RBAC data plane rather than legacy access policies</strong>, vault firewall enabled, key/cert auto-rotation, per-environment vault separation, activity log export destination and retention, and the six default ALZ policies CAF&#39;s Security design area names explicitly (HTTPS on storage, SQL auditing, SQL encryption, no IP forwarding, no inbound RDP from internet, subnet-NSG association).</p><p>SE:11 and SE:12 are process items and reasonably out of reach for a scanner — but they should exist as <code>manual: true</code> rules so they appear in the report as <em>unassessed</em> rather than being invisible.</p><h3 id="cost-optimization-—-6-7-rules-against-14-items" tabindex="-1">Cost Optimization — 6 + 7 rules against 14 items <a class="header-anchor" href="#cost-optimization-—-6-7-rules-against-14-items" aria-label="Permalink to &quot;Cost Optimization — 6 + 7 rules against 14 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Scout</th><th>Verdict</th></tr></thead><tbody><tr><td>CO:01 Culture of financial responsibility</td><td>—</td><td>None</td></tr><tr><td>CO:02 Cost model</td><td>—</td><td>None</td></tr><tr><td>CO:03 Collect and review cost data</td><td><code>CAF-BIL-07</code> anomalies (manual)</td><td>Partial</td></tr><tr><td>CO:04 Spending guardrails</td><td><code>WAF-CO-03</code>, <code>CAF-BIL-01/05</code> budgets</td><td>Partial</td></tr><tr><td>CO:05 Get the best rates</td><td><code>WAF-CO-05</code>, <code>CAF-BIL-06</code> RI/SP (both manual)</td><td>Partial</td></tr><tr><td>CO:06 Align to billing increments</td><td>—</td><td>None</td></tr><tr><td>CO:07 Optimize component costs</td><td><code>WAF-CO-01/04/06</code>, <code>CAF-BIL-02/03/04</code> orphans + Advisor</td><td><strong>Solid</strong></td></tr><tr><td>CO:08 Optimize environment costs</td><td>—</td><td>None</td></tr><tr><td>CO:09 Optimize flow costs</td><td>—</td><td>None</td></tr><tr><td>CO:10 Optimize data costs</td><td><code>WAF-STO-03</code> lifecycle (manual)</td><td>Partial</td></tr><tr><td>CO:11 Optimize code costs</td><td>—</td><td>None (out of scope)</td></tr><tr><td>CO:12 Optimize scaling costs</td><td><code>WAF-PE-04</code> autoscale</td><td>Partial</td></tr><tr><td>CO:13 Optimize personnel time</td><td>—</td><td>None</td></tr><tr><td>CO:14 Consolidation</td><td>—</td><td>None</td></tr></tbody></table><p><strong>Coverage: 1 solid, 5 partial, 8 none ≈ 15–25%.</strong></p><p>Cost is where the cheapest wins are, because CAF&#39;s Governance design area enumerates 12 concrete cost considerations Scout already has the data for and doesn&#39;t check: <strong>Azure Hybrid Benefit</strong> enablement on Windows/SQL VMs, reservation coverage (currently manual and could be automated), savings plan coverage, allowed-region/SKU policies, storage lifecycle policies, Spot VM adoption, and dev/test subscription offer usage.</p><p><code>WAF-CO-01</code>/<code>CAF-BIL-02</code> and <code>WAF-CO-04</code>/<code>CAF-BIL-03</code> are exact duplicates — orphaned disks and orphaned public IPs, checked twice under different IDs. A LandingZone run (<code>caf.* + waf.*</code>) counts both, double-weighting orphan cleanup against the whole framework.</p><h3 id="operational-excellence-—-6-6-rules-against-11-items" tabindex="-1">Operational Excellence — 6 + 6 rules against 11 items <a class="header-anchor" href="#operational-excellence-—-6-6-rules-against-11-items" aria-label="Permalink to &quot;Operational Excellence — 6 + 6 rules against 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Scout</th><th>Verdict</th></tr></thead><tbody><tr><td>OE:01 DevOps culture / standard practices</td><td>—</td><td>None</td></tr><tr><td>OE:02 Formalize operational tasks</td><td><code>WAF-OE-05</code> runbooks (manual)</td><td>Partial</td></tr><tr><td>OE:03 Formalize development practices</td><td>—</td><td>None</td></tr><tr><td>OE:04 Tools and processes</td><td>—</td><td>None</td></tr><tr><td>OE:05 Infrastructure as code</td><td><code>WAF-OE-02/08</code>, <code>CAF-AUT-01/04</code></td><td><strong>Solid</strong></td></tr><tr><td>OE:06 Workload supply chain</td><td><code>CAF-AUT-03/06</code> (both manual)</td><td>Partial</td></tr><tr><td>OE:07 Observability</td><td><code>WAF-OE-01</code>, <code>CAF-MGT-01/05/06</code></td><td><strong>Solid</strong></td></tr><tr><td>OE:08 Incident response</td><td><code>WAF-OE-06</code> alert rules (manual)</td><td>Partial</td></tr><tr><td>OE:09 Testing</td><td>—</td><td>None</td></tr><tr><td>OE:10 Automation</td><td><code>WAF-OE-07</code> (manual)</td><td>Partial</td></tr><tr><td>OE:11 Safe deployment practices</td><td>—</td><td>None</td></tr></tbody></table><p><strong>Coverage: 2 solid, 4 partial, 5 none ≈ 20–30%.</strong></p><p><code>WAF-OE-06</code> (alert rules) is manual with the note <em>&quot;collect.json does not yet collect an alert-rule inventory&quot;</em>, and <code>WAF-OE-07</code> says <em>&quot;No automation-account collector exists yet&quot;</em>. Both are collector gaps, not rule-design gaps — Azure Monitor alert rules and Automation Accounts are both trivially available via ARG. These are the two easiest manual→automated conversions in the repo.</p><p><strong>Numbering warning:</strong> <code>waf.operational.yaml</code> uses <code>WAF-OE-01, 02, 05, 06, 07, 08</code>. Microsoft consolidated OpEx from 12 items to 11 in 2026 (old OE:07 observability and OE:08 instrument-application merged into a single OE:07; everything below renumbered). If these IDs were ever intended to track checklist codes, they now track the <strong>pre-2026</strong> numbering. See <a href="#rule-identity-is-inconsistent">Rule identity is inconsistent</a>.</p><h3 id="performance-efficiency-—-weakest-pillar" tabindex="-1">Performance Efficiency — weakest pillar <a class="header-anchor" href="#performance-efficiency-—-weakest-pillar" aria-label="Permalink to &quot;Performance Efficiency — weakest pillar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Scout</th><th>Verdict</th></tr></thead><tbody><tr><td>PE:01 Performance targets</td><td>—</td><td>None</td></tr><tr><td>PE:02 Capacity planning</td><td><code>WAF-PE-01/06</code> subnet IP headroom</td><td>Partial (network only)</td></tr><tr><td>PE:03 Select the right services</td><td>—</td><td>None</td></tr><tr><td>PE:04 Performance measurement</td><td>—</td><td>None</td></tr><tr><td>PE:05 Scaling and partitioning</td><td><code>WAF-PE-04</code> autoscale (manual)</td><td>Partial</td></tr><tr><td>PE:06 Performance testing</td><td>—</td><td>None</td></tr><tr><td>PE:07 Optimize code and infrastructure</td><td><code>WAF-PE-02/07</code> Advisor</td><td>Partial</td></tr><tr><td>PE:08 Optimize data performance</td><td>—</td><td>None</td></tr><tr><td>PE:09 Prioritize critical flows</td><td>—</td><td>None</td></tr><tr><td>PE:10 Optimize operational tasks</td><td>—</td><td>None</td></tr><tr><td>PE:11 Respond to live performance issues</td><td>—</td><td>None</td></tr><tr><td>PE:12 Continuous performance optimization</td><td><code>WAF-PE-05</code> CDN/caching (manual)</td><td>Partial</td></tr></tbody></table><p><strong>Coverage: 0 solid, 4 partial, 8 none ≈ 10%.</strong></p><p>Four of six rules are about subnet IP exhaustion or Advisor pass-through. There is no check on VM SKU generation currency, disk tier vs workload, SQL service tier, App Service plan tier, or accelerated networking — all directly observable and all squarely PE:03/PE:07.</p><h3 id="waf-totals" tabindex="-1">WAF totals <a class="header-anchor" href="#waf-totals" aria-label="Permalink to &quot;WAF totals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Solid</th><th>Partial</th><th>None</th><th>Rough coverage</th></tr></thead><tbody><tr><td>Reliability</td><td>10</td><td>1</td><td>2</td><td>7</td><td>~20%</td></tr><tr><td>Security</td><td>12</td><td>5</td><td>4</td><td>3</td><td>~55%</td></tr><tr><td>Cost Optimization</td><td>14</td><td>1</td><td>5</td><td>8</td><td>~20%</td></tr><tr><td>Operational Excellence</td><td>11</td><td>2</td><td>4</td><td>5</td><td>~25%</td></tr><tr><td>Performance Efficiency</td><td>12</td><td>0</td><td>4</td><td>8</td><td>~10%</td></tr><tr><td><strong>Total</strong></td><td><strong>59</strong></td><td><strong>9</strong></td><td><strong>19</strong></td><td><strong>31</strong></td><td><strong>~15% solid / ~47% touched</strong></td></tr></tbody></table><hr><h2 id="caf-coverage-matrix" tabindex="-1">CAF coverage matrix <a class="header-anchor" href="#caf-coverage-matrix" aria-label="Permalink to &quot;CAF coverage matrix&quot;">​</a></h2><p>Official source: the 8 Azure landing zone design areas, confirmed still 8 in 2026, now grouped as <strong>environment</strong> (billing/tenant, IAM, resource org, network) and <strong>compliance</strong> (security, management, governance, platform automation). ~394 design recommendations across ~43 pages.</p><table tabindex="0"><thead><tr><th>#</th><th>Design area</th><th>Official recs</th><th>Scout rules</th><th>Coverage</th><th>Headline gaps</th></tr></thead><tbody><tr><td>1</td><td><strong>Azure billing &amp; Entra tenant</strong></td><td>42</td><td><code>caf.billing.yaml</code> — 7</td><td><strong>~5%</strong></td><td>See below — this file is <strong>misnamed</strong></td></tr><tr><td>2</td><td><strong>Identity &amp; access management</strong></td><td>69</td><td><code>caf.identity.yaml</code> — 7</td><td><strong>~10%</strong></td><td>break-glass accounts, workload identity federation, managed identity usage, admin units, entitlement management, Defender for Identity, ABAC conditions, Global Admin count ≤5, per-landing-zone groups</td></tr><tr><td>3</td><td><strong>Resource organization</strong></td><td>35</td><td><code>caf.resourceorg.yaml</code> — 6 (+<code>CAF-GOV-06</code>)</td><td><strong>~17%</strong></td><td>MG RBAC authorization enabled, default MG for new subscriptions, 3–4 level depth cap, dedicated platform subscriptions (mgmt/security/connectivity/identity), Service Health enabled per subscription, tenant transfer set to <code>Permit no one</code>, the five CAF tag categories, Sandbox/Decommissioned MGs, <strong>new default Security and Local MGs</strong></td></tr><tr><td>4</td><td><strong>Network topology &amp; connectivity</strong></td><td>141</td><td><code>caf.network.yaml</code> — 7</td><td><strong>~5%</strong></td><td>the largest area, the thinnest coverage — see below</td></tr><tr><td>5</td><td><strong>Security</strong></td><td>~100 (45 hub + 19 Zero Trust + 12 encryption + …)</td><td><code>caf.security.yaml</code> — 7</td><td><strong>~10%</strong></td><td>KV RBAC data plane vs access policies, vault firewall, key/cert rotation, per-env vault separation, CMK-vs-MMK default, activity log export + retention, Azure Attestation, the 6 default ALZ policies, Zero Trust&#39;s 7 pillars</td></tr><tr><td>6</td><td><strong>Management</strong></td><td>46 (22 recs + 5 BCDR)</td><td><code>caf.management.yaml</code> — 6</td><td><strong>~13%</strong></td><td>single-LAW design, immutable WORM export beyond 7 years, locks on shared services, Traffic Analytics, service/resource health alerts, <strong>the entire BCDR child page</strong> (ASR replication, drills, PaaS-native DR, no overlapping prod/DR IP ranges, Key Vault DR), Automanage machine-config drift, Service Groups, Azure Monitor health models</td></tr><tr><td>7</td><td><strong>Governance</strong></td><td>42 (10 recs + 32 cons)</td><td><code>caf.governance.yaml</code> — 7</td><td><strong>~17%</strong></td><td><strong>policy compliance state (collected, unused)</strong>, regulatory compliance initiatives (HIPAA/PCI-DSS/SOC 2), definitions at root MG, root-MG assignment limits, append-mode required tags, resource-provider registration control, Hybrid Benefit, reservations, savings plans, allowed region/SKU policies, Spot VMs</td></tr><tr><td>8</td><td><strong>Platform automation &amp; DevOps</strong></td><td>~80 across 8 children</td><td><code>caf.platformauto.yaml</code> — 6</td><td><strong>~8%</strong></td><td>policy exemption process, <strong><code>deny</code> preferred over <code>modify</code></strong>, OIDC/workload identity federation vs client secrets (partly observable via Entra app credentials), per-environment deploy identities, service-connection scoping, 4-eyes / branch policies</td></tr></tbody></table><p><strong>CAF total: 53 rules against ~394 recommendations ≈ 10%.</strong></p><h3 id="area-1-is-misnamed-and-that-hides-the-gap" tabindex="-1">Area 1 is misnamed, and that hides the gap <a class="header-anchor" href="#area-1-is-misnamed-and-that-hides-the-gap" aria-label="Permalink to &quot;Area 1 is misnamed, and that hides the gap&quot;">​</a></h3><p><code>caf.billing.yaml</code> contains cost-optimization rules — budgets, orphaned disks, orphaned public IPs, Advisor cost items, RI/savings-plan review, cost anomalies. <strong>None of that is the CAF &quot;Azure billing and Microsoft Entra tenant&quot; design area</strong>, which is about EA/MCA/CSP enrollment structure, department and account hierarchy, notification contacts, subscription vending, <code>DA View Charges</code> / <code>AO View Charges</code>, MFA on subscription creators, custom domains, SSO topology, break-glass accounts, and tenant-count discipline.</p><p>Scout&#39;s Area 1 coverage is effectively <strong><code>CAF-BIL-01</code> (budgets exist), and nothing else</strong> — roughly 1 of 42 recommendations. The file&#39;s name makes the area look covered on the registry&#39;s <code>Frameworks</code> list when it is not. It also means the six <code>WAF-CO-*</code> rules and the seven <code>CAF-BIL-*</code> rules are the same subject matter filed under two different frameworks, with two literal duplicates between them.</p><h3 id="area-4-is-the-biggest-single-gap" tabindex="-1">Area 4 is the biggest single gap <a class="header-anchor" href="#area-4-is-the-biggest-single-gap" aria-label="Permalink to &quot;Area 4 is the biggest single gap&quot;">​</a></h3><p>141 recommendations, 7 rules. The uncovered list includes items that are both high-consequence and cheaply checkable from ARG:</p><ul><li><strong>NAT Gateway for outbound</strong> — CAF says never rely on Azure default outbound access (which retires).</li><li><strong>Non-AZ VPN gateway SKUs (VpnGw1–5) retire 30 September 2026.</strong> Scout checks <code>CAF-NET-05</code> active-active but not zone-redundant SKU. This is a dated migration deadline inside the audit window.</li><li><strong>NSG flow logs retire 30 September 2027</strong>, no new ones after 30 June 2025 — migration to VNet flow logs is unchecked.</li><li>Azure Firewall <strong>Management NIC</strong> enabled and a ≥<code>/26</code> <code>AzureFirewallManagementSubnet</code>; Firewall Premium for TLS inspection/IDPS.</li><li><strong>No public IPs on VM management ports; Bastion for remote access</strong> — CAF calls this out explicitly and it is the classic ALZ review finding.</li><li>NSG on <strong>every</strong> subnet; ASGs for multitier workloads.</li><li>WAF policy on Front Door / Application Gateway; Application Gateway in the spoke, not the hub.</li><li>Reserved/invalid IP ranges (<code>224.0.0.0/4</code>, <code>127.0.0.0/8</code>, <code>169.254.0.0/16</code>, <code>168.63.129.16/32</code>); oversized <code>/16</code> VNets; IPv6 subnets must be exactly <code>/64</code>.</li><li>DNS Private Resolver with two dedicated ≥<code>/28</code> subnets; <code>privatelink.*</code> zones in the connectivity subscription.</li><li>Dual ExpressRoute circuits from <strong>different peering locations</strong>.</li></ul><p><code>CAF-NET-03</code> (subnet IP utilization) is duplicated as <code>WAF-PE-01</code>/<code>WAF-PE-06</code> — three rules on subnet headroom, against zero rules on any of the above.</p><h3 id="what-caf-changed-that-scout-doesn-t-reflect" tabindex="-1">What CAF changed that Scout doesn&#39;t reflect <a class="header-anchor" href="#what-caf-changed-that-scout-doesn-t-reflect" aria-label="Permalink to &quot;What CAF changed that Scout doesn&#39;t reflect&quot;">​</a></h3><ul><li><strong>Two new default management groups</strong>: <code>Security</code> (under Platform, for Sentinel/SIEM tooling) and <code>Local</code> (Azure Local clusters). <code>CAF-GOV-06</code>&#39;s manual remediation text describes the <strong>old</strong> archetype — &quot;Platform (Management/Identity/Connectivity) … Landing Zones (Corp/Online) and Sandbox&quot; — with no Security, no Local, no Decommissioned.</li><li><strong>The five CAF governance disciplines are retired.</strong> Cost Management, Security Baseline, Identity Baseline, Resource Consistency, and Deployment Acceleration now all 301-redirect to <code>govern/enforce-cloud-governance-policies</code>. The current Govern methodology is five steps (build team → assess risks → document policies → enforce policies → monitor compliance) with a seven-category taxonomy: <strong>RC</strong> regulatory compliance, <strong>SC</strong> security, <strong>CM</strong> cost management, <strong>OP</strong> operations, <strong>DG</strong> data, <strong>RM</strong> resource management, <strong>AI</strong> AI. Any Scout documentation or roadmap still using discipline vocabulary is against a dead model.</li><li><strong>Sovereignty moved out of CAF</strong> to a separate <code>/azure/azure-sovereign-clouds/</code> docset; &quot;Microsoft Cloud for Sovereignty&quot; is now &quot;Microsoft Sovereign Cloud&quot;.</li><li><strong>AI does not need its own landing zone</strong> — CAF&#39;s FAQ says so explicitly. Any future rule flagging a missing AI landing zone would score against guidance that says the opposite.</li><li><strong>Microsoft&#39;s own Azure Landing Zone Review</strong> (34 questions) weights the areas very unevenly: Network 11, Identity 7, Platform automation 4, Billing 3, Resource org 3, Governance 3, Management 2, Security 2. Scout&#39;s registry weights every rule file at <code>weight: 1.0</code>. Worth a deliberate decision rather than a default.</li></ul><hr><h2 id="rule-quality-assessment" tabindex="-1">Rule quality assessment <a class="header-anchor" href="#rule-quality-assessment" aria-label="Permalink to &quot;Rule quality assessment&quot;">​</a></h2><p>101 of 148 rules are automated; 47 are <code>manual: true</code>. Assert types:</p><table tabindex="0"><thead><tr><th>Assert</th><th>Count</th><th>Comment</th></tr></thead><tbody><tr><td><code>countEquals</code></td><td>57</td><td>Usually <code>value: 0</code> — &quot;no resources violate X&quot;. Sound pattern.</td></tr><tr><td><code>manual</code></td><td>47</td><td>No verdict produced.</td></tr><tr><td><code>exists</code></td><td>16</td><td><strong>The problem class</strong> — see below.</td></tr><tr><td><code>countGreaterThan</code></td><td>14</td><td>Mostly <code>value: 0</code>, same weakness as <code>exists</code>.</td></tr><tr><td><code>percentageAtLeast</code></td><td>11</td><td><strong>The best pattern in the repo.</strong></td></tr><tr><td><code>countLessThan</code></td><td>2</td><td></td></tr><tr><td><code>notExists</code></td><td>1</td><td></td></tr></tbody></table><h3 id="the-good" tabindex="-1">The good <a class="header-anchor" href="#the-good" aria-label="Permalink to &quot;The good&quot;">​</a></h3><p><code>percentageAtLeast</code> rules are genuinely meaningful and are what the rest of the corpus should look like:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">WAF-OE-08</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$.management.deployments[?(@.properties.templateHash)]&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">percentageAtLeast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">70</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">denominatorQuery</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$.management.deployments[*]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>That measures a <em>ratio</em> against a denominator, so it can&#39;t be satisfied by a single token resource. <code>CAF-MGT-04</code> (backup coverage across the VM estate), <code>CAF-RES-06</code> (environment tag coverage), and <code>CAF-IDN-05</code> (share of privileged assignments that are PIM-eligible) are all in this class and all defensible.</p><p><code>WAF-RE-05</code> is a good example of a rule that has been thought about — it scopes to <code>zoneEligible == true</code> so SKUs and regions without zone support don&#39;t generate false negatives, with a comment explaining why. <code>caf.storage.yaml</code>&#39;s TLS/HTTPS/public-access rules and <code>caf.containers.yaml</code>&#39;s eight AKS/ACR rules are straightforward, correct, and check the right properties.</p><p>The manual rules are also, mostly, <em>honestly</em> manual. Several state exactly which collector field is missing and give the <code>az</code> command to check by hand — e.g. <code>WAF-STO-04</code>: <em>&quot;collect.json does not yet capture deleteRetentionPolicy.days — verify via <code>az storage account blob-service-properties show</code>&quot;</em>. That is good practice and makes the backlog self-documenting.</p><h3 id="the-shallow" tabindex="-1">The shallow <a class="header-anchor" href="#the-shallow" aria-label="Permalink to &quot;The shallow&quot;">​</a></h3><p><strong>16 <code>exists</code> rules pass on a single matching resource anywhere in the tenant.</strong> The worst offenders:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Query</th><th>Why it&#39;s weak</th></tr></thead><tbody><tr><td><code>CAF-GOV-03</code> &quot;Resource locks <strong>protect critical scopes</strong>&quot;</td><td><code>$.governance.resourceLocks[*]</code></td><td>One lock on one dev resource group passes. Nothing checks <em>which</em> scopes are locked.</td></tr><tr><td><code>CAF-SEC-03</code> &quot;Private endpoints used for PaaS data services&quot;</td><td><code>$.networking.privateEndpoints[*]</code></td><td>One private endpoint anywhere passes. Should be a ratio over PaaS data services.</td></tr><tr><td><code>CAF-SEC-06</code> &quot;Private DNS zones support private endpoint name resolution&quot;</td><td><code>$.networking.privateDnsZones[*]</code></td><td>Any private DNS zone passes — doesn&#39;t check for <code>privatelink.*</code> zones, or that they match the private endpoints in use.</td></tr><tr><td><code>CAF-HYB-02</code> &quot;Arc footprint is present&quot;</td><td><code>$.domains.hybrid.arcServers[*]</code></td><td>One Arc server passes.</td></tr><tr><td><code>CAF-IDN-02</code> &quot;PIM eligibility in use&quot;</td><td><code>$.governance.pimEligibility[*]</code></td><td>One eligible assignment passes. Mitigated by <code>CAF-IDN-05</code>, which does the ratio properly — so the shallow version adds noise, not signal.</td></tr><tr><td><code>CAF-RES-03</code> &quot;Consistent tag values per key across subscriptions&quot;</td><td><code>$.tags[*]</code></td><td>Asserts tags exist. Does not check consistency at all. <strong>The title claims something the query cannot test.</strong></td></tr><tr><td><code>CAF-SEC-02</code> &quot;Defender for Cloud enabled&quot;</td><td><code>$.security.defenderPlans[?(@.properties.pricingTier == &#39;Standard&#39;)]</code></td><td>One Standard plan on one subscription passes for the whole tenant.</td></tr></tbody></table><h3 id="the-wrong" tabindex="-1">The wrong <a class="header-anchor" href="#the-wrong" aria-label="Permalink to &quot;The wrong&quot;">​</a></h3><p>Two rules are semantically incorrect, not merely shallow:</p><p><strong><code>CAF-GOV-05</code> — &quot;DeployIfNotExists / Modify assignments enforce configuration drift correction&quot;</strong></p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$.governance.policyAssignments[?(@.properties.parameters)]&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The query selects assignments that have a <strong><code>parameters</code> block</strong>. Having parameters has nothing to do with having a <code>DeployIfNotExists</code> or <code>Modify</code> effect — most parameterised assignments are <code>Audit</code> or <code>Deny</code>. This rule will pass in essentially every tenant with any parameterised policy assignment, and will report drift-correction enforcement that does not exist. <strong>This is a false-pass on a high-value control.</strong></p><p><strong><code>CAF-AUT-02</code> — &quot;Policy-as-code / DINE assignments deploy configuration&quot;</strong> uses the <em>identical</em> query and has the <em>identical</em> flaw.</p><p>Both need to inspect the policy <strong>definition&#39;s</strong> effect, or the assignment&#39;s effect override — not the presence of a parameters bag.</p><p><strong><code>WAF-RE-09</code></strong> (covered above) — asserts backup exists and is titled/scored as the disaster recovery checklist item.</p><h3 id="rule-identity-is-inconsistent" tabindex="-1">Rule identity is inconsistent <a class="header-anchor" href="#rule-identity-is-inconsistent" aria-label="Permalink to &quot;Rule identity is inconsistent&quot;">​</a></h3><p>The ID schemes don&#39;t agree with each other, which will make any future checklist mapping painful:</p><ul><li><code>waf.reliability.yaml</code> uses <code>WAF-RE-05, 09, 03</code> — non-sequential, clearly intended as <strong>WAF checklist codes</strong> RE:05/RE:09/RE:03.</li><li><code>waf.performance.yaml</code> uses <code>PE-01, 02, 04, 05, 06, 07</code> — skips 03, so also apparently checklist codes, but <code>WAF-PE-01</code> maps to capacity/IP headroom which is PE:02, not PE:01.</li><li><code>waf.operational.yaml</code> uses <code>OE-01, 02, 05, 06, 07, 08</code> — skips 03 and 04, against the <strong>pre-2026</strong> 12-item numbering.</li><li><code>waf.security.yaml</code> uses <code>SE-01…07</code> sequentially — these are <strong>not</strong> checklist codes (<code>WAF-SE-07</code> &quot;secrets in Key Vault&quot; is SE:09; <code>WAF-SE-06</code> &quot;threat detection&quot; is SE:10).</li><li><code>waf.cost.yaml</code> uses <code>CO-01…06</code> sequentially — also not checklist codes.</li></ul><p>So the corpus is half-mapped to Microsoft&#39;s codes and half not, with no field recording which. There is no <code>control:</code> or <code>checklistItem:</code> key in the schema — the mapping is <em>implied by the ID</em>, inconsistently. <strong>Any coverage reporting Scout wants to produce against WAF requires an explicit mapping field.</strong></p><h3 id="duplication" tabindex="-1">Duplication <a class="header-anchor" href="#duplication" aria-label="Permalink to &quot;Duplication&quot;">​</a></h3><p>Rules duplicated across files, each counted separately in a <code>LandingZone</code> run:</p><table tabindex="0"><thead><tr><th>Subject</th><th>Rules</th></tr></thead><tbody><tr><td>Orphaned managed disks</td><td><code>WAF-CO-01</code>, <code>CAF-BIL-02</code></td></tr><tr><td>Orphaned public IPs</td><td><code>WAF-CO-04</code>, <code>CAF-BIL-03</code></td></tr><tr><td>RI / Savings Plan coverage</td><td><code>WAF-CO-05</code>, <code>CAF-BIL-06</code></td></tr><tr><td>Diagnostic settings coverage ≥80%</td><td><code>WAF-OE-01</code>, <code>CAF-MGT-01</code> (identical query and assert)</td></tr><tr><td>IaC deployments present</td><td><code>WAF-OE-02</code>, <code>CAF-AUT-01</code> (identical)</td></tr><tr><td>IaC deployment ratio ≥70%</td><td><code>WAF-OE-08</code>, <code>CAF-AUT-04</code></td></tr><tr><td>Policy <code>parameters</code> heuristic</td><td><code>CAF-GOV-05</code>, <code>CAF-AUT-02</code> (identical, both wrong)</td></tr><tr><td>Backup items present</td><td><code>WAF-RE-09</code>, <code>CAF-MGT-02</code></td></tr><tr><td>Subnet IP headroom</td><td><code>CAF-NET-03</code>, <code>WAF-PE-01</code>, <code>WAF-PE-06</code></td></tr></tbody></table><p>That is ~17 rules of overlap — <strong>11% of the corpus</strong> — which inflates the headline count and skews <code>LandingZone</code> scoring toward whatever happens to be double-filed.</p><hr><h2 id="the-waf-storage-yaml-anomaly" tabindex="-1">The <code>waf.storage.yaml</code> anomaly <a class="header-anchor" href="#the-waf-storage-yaml-anomaly" aria-label="Permalink to &quot;The \`waf.storage.yaml\` anomaly&quot;">​</a></h2><p><strong>Storage is not a WAF pillar. There are exactly five, and there never has been a sixth.</strong></p><p>But the file is not arbitrary — it maps onto a real Microsoft concept that Scout has mislabelled. Microsoft publishes <strong>service guides</strong> (<code>/azure/well-architected/service-guides/&lt;service&gt;</code>) grouped into service <em>categories</em>, and one of those categories is literally <strong>Storage</strong> (Azure Blob Storage, Azure Files, Azure NetApp Files, Disk Storage). Critically, <strong>each service guide is itself organised by the five pillars</strong>. So &quot;Storage&quot; in Microsoft&#39;s taxonomy is a <em>service axis</em>, orthogonal to the pillar axis — not a peer of Reliability.</p><p><code>waf.storage.yaml</code> declares <code>area: &quot;Storage reliability&quot;</code>, which shows the intent was right. Its five rules are: redundancy SKU (RE:05), Advisor reliability items (RE:10-ish), lifecycle policy (CO:10), soft-delete retention (RE:09), and failover readiness (RE:09). They are <strong>Reliability and Cost items scoped to storage</strong>, and four of the five are <code>manual: true</code>.</p><p><strong>Recommendation:</strong> fold the contents into the pillar files with a service tag rather than keeping a pseudo-pillar.</p><ul><li><code>WAF-STO-01</code> (redundancy SKU) → <code>waf.reliability.yaml</code> as an RE:05 rule. This alone takes Reliability from 3 rules to 4 and gives RE:05 storage coverage inside the pillar that scores it.</li><li><code>WAF-STO-04</code> (soft-delete retention) and <code>WAF-STO-05</code> (GRS/GZRS failover readiness) → <code>waf.reliability.yaml</code> under RE:09, where they materially improve the DR story that <code>WAF-RE-09</code> currently fakes.</li><li><code>WAF-STO-03</code> (lifecycle policy) → <code>waf.cost.yaml</code> under CO:10.</li><li><code>WAF-STO-02</code> (Advisor reliability on storage) → merge into a general Advisor-reliability rule in <code>waf.reliability.yaml</code>; it is redundant with the Advisor pattern used in every other pillar.</li><li>Delete <code>waf.storage.yaml</code>; update the <code>Storage</code> assessment in <code>manifests/assessments.psd1:88</code> from <code>Rules = @(&#39;caf.storage&#39;, &#39;waf.storage&#39;)</code> to <code>@(&#39;caf.storage&#39;, &#39;waf.reliability&#39;, &#39;waf.cost&#39;)</code> — or, better, introduce a service-scoping mechanism (below).</li></ul><p><strong>Note this is not a cosmetic fix.</strong> As long as <code>waf.storage</code> exists, the <code>LandingZone</code> roll-up&#39;s <code>Rules = @(&#39;caf.*&#39;, &#39;waf.*&#39;)</code> glob pulls in a sixth &quot;pillar&quot; and reports six WAF areas to the customer. Any per-pillar scoring or radar chart Scout renders is structurally wrong.</p><p>The same conflation exists on the CAF side: of the 17 <code>caf.*</code> files, <strong>8 are genuine CAF design areas</strong> (billing, identity, resourceorg, network, security, management, governance, platformauto) and <strong>9 are service domains</strong> (ai, analytics, containers, databases, hybrid, integration, iot, storage, web). The nine service-domain files contain overwhelmingly <em>security-hardening</em> rules — public network access, TLS, managed identity, private endpoints — which belong to CAF&#39;s Security design area and WAF&#39;s SE:06/SE:07/SE:08. Filing them as if they were CAF areas means <strong>CAF area coverage looks like 17 areas when there are 8</strong>, and the Security area looks like it has 7 rules when it really has ~60 spread across ten files.</p><hr><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><h3 id="recommendation-1-restructure-the-rule-namespace-around-the-two-real-axes" tabindex="-1">Recommendation 1: restructure the rule namespace around the two real axes <a class="header-anchor" href="#recommendation-1-restructure-the-rule-namespace-around-the-two-real-axes" aria-label="Permalink to &quot;Recommendation 1: restructure the rule namespace around the two real axes&quot;">​</a></h3><p>The single highest-leverage change. Today one flat <code>framework.domain</code> namespace encodes three different things (CAF design areas, WAF pillars, service domains), which is why Reliability appears to have 3 rules while zone-redundancy evidence for six other services sits in files Reliability never reads.</p><p>Give every rule two explicit mapping fields alongside its existing home:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">CAF-DB-02</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Production SQL databases are zone-redundant&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">databases</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # service axis</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  caf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">security</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CAF design area(s)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  waf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">RE:05</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># WAF checklist code(s)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Then a &quot;Reliability&quot; run selects on <code>waf: RE:*</code> regardless of which file the rule lives in, and a &quot;Databases&quot; run selects on <code>service: databases</code>. This is what makes honest per-pillar and per-area coverage reporting possible — and it is a precondition for every other recommendation here.</p><p>It also fixes duplication cleanly: <code>WAF-CO-01</code> and <code>CAF-BIL-02</code> become one rule tagged <code>caf: [governance]</code>, <code>waf: [CO:07]</code>.</p><h3 id="recommendation-2-fix-the-wizard-then-the-two-false-pass-rules" tabindex="-1">Recommendation 2: fix the wizard, then the two false-pass rules <a class="header-anchor" href="#recommendation-2-fix-the-wizard-then-the-two-false-pass-rules" aria-label="Permalink to &quot;Recommendation 2: fix the wizard, then the two false-pass rules&quot;">​</a></h3><p>Ordered by ratio of harm to effort:</p><ol><li>The wizard path (one line, plus a test) — 21 assessments are invisible today.</li><li><code>CAF-GOV-05</code> and <code>CAF-AUT-02</code> — currently report drift-correction enforcement that doesn&#39;t exist. A false pass is worse than no rule.</li><li><code>WAF-RE-09</code> — retitle to what it checks (&quot;Backup configured&quot;) and add real DR rules for RE:09.</li><li><code>CAF-RES-03</code> — the title promises tag-value consistency; the query checks tags exist. Either implement the consistency check or retitle.</li></ol><h3 id="recommendation-3-score-the-policy-compliance-data-already-being-collected" tabindex="-1">Recommendation 3: score the policy compliance data already being collected <a class="header-anchor" href="#recommendation-3-score-the-policy-compliance-data-already-being-collected" aria-label="Permalink to &quot;Recommendation 3: score the policy compliance data already being collected&quot;">​</a></h3><p>Scout already pulls <code>PolicyComplianceStates</code>, <code>nonCompliantResources</code>, <code>nonCompliantPolicies</code>, and the <code>policyStates/latest/summarize</code> API — and no rule reads any of it. Adding compliance-state rules to <code>caf.governance.yaml</code> requires <strong>no new collector work</strong> and would take Governance from &quot;policy assignments exist&quot; to actual governance measurement. Highest value-per-hour item in this audit after the wizard.</p><p>The same applies, at slightly higher cost, to two collector gaps whose absence is already documented in rule comments: <strong>Azure Monitor alert rules</strong> (<code>WAF-OE-06</code>) and <strong>Automation Accounts</strong> (<code>WAF-OE-07</code>). Both are single ARG queries and both convert a manual rule to automated.</p><h3 id="recommendation-4-new-assessments" tabindex="-1">Recommendation 4: new assessments <a class="header-anchor" href="#recommendation-4-new-assessments" aria-label="Permalink to &quot;Recommendation 4: new assessments&quot;">​</a></h3><p><strong>Per WAF pillar (5 new).</strong> <code>Reliability</code>, <code>Security</code>, <code>CostOptimization</code>, <code>OperationalExcellence</code>, <code>PerformanceEfficiency</code>. This is what customers ask for by name, it matches Microsoft&#39;s own Well-Architected Review, and it is what makes a pillar radar chart meaningful. Today there is no way to run &quot;assess my Reliability&quot; — the closest is <code>Compute</code>, which bundles reliability, cost, and performance for VMs only. Depends on Recommendation 1.</p><p><strong>Per CAF design area (8 new).</strong> <code>Billing</code> (properly scoped to enrollment/tenant, not cost), <code>IdentityAccess</code>, <code>ResourceOrganization</code>, <code>NetworkTopology</code>, <code>SecurityBaseline</code>, <code>ManagementBaseline</code>, <code>Governance</code> (exists but should be promoted from sub-bundle to full area), <code>PlatformAutomation</code>. Aligns Scout&#39;s output with Microsoft&#39;s Azure Landing Zone Review, so a customer can compare Scout&#39;s result to the official 34-question assessment.</p><p><strong>Compliance frameworks (new class).</strong> Worth doing, and Scout is closer than it looks — Defender for Cloud&#39;s regulatory compliance API exposes assessment results for <strong>MCSB (Microsoft Cloud Security Benchmark)</strong>, CIS Azure Foundations, NIST SP 800-53, PCI-DSS, ISO 27001, and SOC 2 as first-party data. That means a compliance assessment is largely an <em>ingest-and-map</em> job rather than 200 hand-written rules.</p><p>Priority order: <strong>MCSB first</strong> (it is the Azure-native baseline, it is what Defender scores against by default, and it maps cleanly onto WAF SE:01), then <strong>CIS Azure Foundations</strong> (most requested in practice), then NIST/ISO/PCI as ingest targets. Recommend a <code>Compliance</code> assessment with a <code>-Framework</code> selector rather than five separate registry entries.</p><p><strong>Anti-recommendation:</strong> do not build a separate &quot;AI landing zone&quot; assessment. CAF explicitly states no separate AI landing zone is needed. Extend <code>caf.ai.yaml</code> within the existing areas instead.</p><h3 id="recommendation-5-track-framework-currency" tabindex="-1">Recommendation 5: track framework currency <a class="header-anchor" href="#recommendation-5-track-framework-currency" aria-label="Permalink to &quot;Recommendation 5: track framework currency&quot;">​</a></h3><p>CAF and WAF both moved materially in 2025–2026 and Scout is scoring against a stale snapshot in at least four places (OpEx 12→11 items, the two new default MGs, the retired governance disciplines, sovereignty leaving CAF). There is no mechanism to notice this. A dated <code>frameworkVersion:</code> header per rule file, plus a periodic review task, would at least make staleness visible.</p><p>Two dated deadlines fall inside the next audit window and should become rules now: <strong>non-AZ VPN gateway SKUs (VpnGw1–5) retire 30 September 2026</strong>, and <strong>NSG flow logs retire 30 September 2027</strong> (no new ones since 30 June 2025).</p><hr><h2 id="proposed-work-breakdown-under-ab-6447" tabindex="-1">Proposed work breakdown under AB#6447 <a class="header-anchor" href="#proposed-work-breakdown-under-ab-6447" aria-label="Permalink to &quot;Proposed work breakdown under AB#6447&quot;">​</a></h2><p>Sized S/M/L. The first three are independent of the restructure and can start immediately.</p><h3 id="phase-0-—-defects-do-first" tabindex="-1">Phase 0 — defects (do first) <a class="header-anchor" href="#phase-0-—-defects-do-first" aria-label="Permalink to &quot;Phase 0 — defects (do first)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Size</th></tr></thead><tbody><tr><td>0.1</td><td><strong>Fix <code>Start-AZSCWizard.ps1:238</code> manifest path</strong>; replace silent <code>Test-Path</code> fallback with a visible warning; add Pester coverage asserting all 22 assessments are offered</td><td>S</td></tr><tr><td>0.2</td><td>Fix <code>CAF-GOV-05</code> and <code>CAF-AUT-02</code> — inspect policy effect, not the presence of a <code>parameters</code> block</td><td>S</td></tr><tr><td>0.3</td><td>Retitle <code>WAF-RE-09</code> to &quot;Backup configured&quot;; fix <code>CAF-RES-03</code> title-vs-query mismatch</td><td>S</td></tr><tr><td>0.4</td><td>Decide and document the wizard&#39;s <code>-DefaultSelected</code> behaviour now that the full list is reachable</td><td>S</td></tr></tbody></table><h3 id="phase-1-—-free-wins-from-existing-data" tabindex="-1">Phase 1 — free wins from existing data <a class="header-anchor" href="#phase-1-—-free-wins-from-existing-data" aria-label="Permalink to &quot;Phase 1 — free wins from existing data&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Size</th></tr></thead><tbody><tr><td>1.1</td><td>Add Azure Policy <strong>compliance-state</strong> rules to <code>caf.governance.yaml</code> using already-collected <code>PolicyComplianceStates</code> / <code>nonCompliantResources</code></td><td>M</td></tr><tr><td>1.2</td><td>Add an Azure Monitor <strong>alert-rule</strong> collector; convert <code>WAF-OE-06</code> from manual to automated</td><td>M</td></tr><tr><td>1.3</td><td>Add an <strong>Automation Account</strong> collector; convert <code>WAF-OE-07</code> from manual to automated</td><td>S</td></tr><tr><td>1.4</td><td>Automate <code>WAF-CO-05</code> / <code>CAF-BIL-06</code> reservation and savings-plan coverage from Cost Management data</td><td>M</td></tr></tbody></table><h3 id="phase-2-—-structural" tabindex="-1">Phase 2 — structural <a class="header-anchor" href="#phase-2-—-structural" aria-label="Permalink to &quot;Phase 2 — structural&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Size</th></tr></thead><tbody><tr><td>2.1</td><td>Add <code>service:</code>, <code>caf:</code>, <code>waf:</code> mapping fields to the rule schema; backfill all 148 rules; update the rule interpreter and registry to select on them</td><td>L</td></tr><tr><td>2.2</td><td><strong>Retire <code>waf.storage.yaml</code></strong> — redistribute its 5 rules to <code>waf.reliability</code> and <code>waf.cost</code>; update the <code>Storage</code> assessment&#39;s <code>Rules</code></td><td>S</td></tr><tr><td>2.3</td><td>De-duplicate the ~17 overlapping rules identified above</td><td>M</td></tr><tr><td>2.4</td><td>Rename/rescope <code>caf.billing.yaml</code> — move its cost rules to the WAF Cost pillar, and create genuine CAF Area 1 (enrollment/tenant) rules</td><td>M</td></tr><tr><td>2.5</td><td>Reclassify the 9 service-domain <code>caf.*</code> files so CAF area coverage reports 8 areas, not 17</td><td>M</td></tr></tbody></table><h3 id="phase-3-—-coverage-depth-largest-body-of-work-per-area-per-pillar-child-tasks" tabindex="-1">Phase 3 — coverage depth (largest body of work; per-area/per-pillar child tasks) <a class="header-anchor" href="#phase-3-—-coverage-depth-largest-body-of-work-per-area-per-pillar-child-tasks" aria-label="Permalink to &quot;Phase 3 — coverage depth (largest body of work; per-area/per-pillar child tasks)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Size</th></tr></thead><tbody><tr><td>3.1</td><td><strong>Reliability</strong> — RE:04, RE:06, RE:07, RE:10; real DR rules (ASR replication, region pairing, no overlapping prod/DR IP ranges, Key Vault DR)</td><td>L</td></tr><tr><td>3.2</td><td><strong>Performance Efficiency</strong> — PE:03/PE:07 service-tier and SKU-currency rules (VM generation, disk tier, SQL tier, App Service plan, accelerated networking)</td><td>M</td></tr><tr><td>3.3</td><td><strong>Network topology</strong> — the highest-count gap: NAT Gateway/default outbound, Firewall Management NIC + Premium, Bastion + no public management ports, NSG-per-subnet, WAF policies, reserved/oversized IP ranges, DNS Private Resolver, dual-ER peering locations, <strong>VpnGw non-AZ SKU retirement</strong>, <strong>NSG flow log migration</strong></td><td>L</td></tr><tr><td>3.4</td><td><strong>Security / Key Vault depth</strong> — RBAC data plane vs access policies, vault firewall, key/cert rotation, per-env separation, CMK-vs-MMK, activity log export + retention, the 6 default ALZ policies</td><td>M</td></tr><tr><td>3.5</td><td><strong>Management</strong> — single-LAW design, WORM export beyond 7 years, service/resource health alerts, Automanage machine-config drift, locks on shared services</td><td>M</td></tr><tr><td>3.6</td><td><strong>Resource organization</strong> — MG RBAC authorization, default MG for new subscriptions, depth cap, dedicated platform subscriptions, Service Health per subscription, tenant transfer <code>Permit no one</code>, the five CAF tag categories</td><td>M</td></tr><tr><td>3.7</td><td><strong>Cost</strong> — Hybrid Benefit, allowed region/SKU policies, Spot adoption, dev/test offer, storage lifecycle</td><td>M</td></tr><tr><td>3.8</td><td><strong>Identity</strong> — break-glass accounts, Global Admin count, workload identity federation vs client secrets, admin units, entitlement management, ABAC conditions</td><td>M</td></tr><tr><td>3.9</td><td>Add <code>manual: true</code> placeholder rules for legitimately unassessable checklist items (SE:02, SE:11, SE:12, OE:01, OE:03, OE:09, RE:01, RE:02, RE:08, CO:01, CO:02, PE:01, PE:06) so the report shows them as <strong>unassessed</strong> rather than invisible</td><td>S</td></tr></tbody></table><h3 id="phase-4-—-new-assessments" tabindex="-1">Phase 4 — new assessments <a class="header-anchor" href="#phase-4-—-new-assessments" aria-label="Permalink to &quot;Phase 4 — new assessments&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Size</th></tr></thead><tbody><tr><td>4.1</td><td>5 per-WAF-pillar assessments (depends on 2.1)</td><td>M</td></tr><tr><td>4.2</td><td>8 per-CAF-design-area assessments (depends on 2.1, 2.4, 2.5)</td><td>M</td></tr><tr><td>4.3</td><td><code>Compliance</code> assessment with <code>-Framework</code> selector; ingest Defender for Cloud regulatory compliance results — <strong>MCSB first</strong>, then CIS Azure Foundations</td><td>L</td></tr><tr><td>4.4</td><td>NIST SP 800-53 / ISO 27001 / PCI-DSS as additional ingest targets under 4.3</td><td>M</td></tr></tbody></table><h3 id="phase-5-—-currency" tabindex="-1">Phase 5 — currency <a class="header-anchor" href="#phase-5-—-currency" aria-label="Permalink to &quot;Phase 5 — currency&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Size</th></tr></thead><tbody><tr><td>5.1</td><td>Add <code>frameworkVersion:</code> headers; refresh <code>CAF-GOV-06</code> for the new Security and Local management groups; purge retired governance-discipline vocabulary from rules and docs</td><td>S</td></tr><tr><td>5.2</td><td>Establish a periodic CAF/WAF currency review against Microsoft Learn &quot;what&#39;s new&quot;</td><td>S</td></tr></tbody></table><hr><h2 id="appendix-—-rule-inventory" tabindex="-1">Appendix — rule inventory <a class="header-anchor" href="#appendix-—-rule-inventory" aria-label="Permalink to &quot;Appendix — rule inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Area declared</th><th>Rules</th><th>Manual</th></tr></thead><tbody><tr><td><code>caf.ai.yaml</code></td><td>AI</td><td>5</td><td>1</td></tr><tr><td><code>caf.analytics.yaml</code></td><td>Analytics</td><td>5</td><td>2</td></tr><tr><td><code>caf.billing.yaml</code></td><td>Billing (<strong>misnamed — is cost</strong>)</td><td>7</td><td>2</td></tr><tr><td><code>caf.containers.yaml</code></td><td>Containers</td><td>8</td><td>1</td></tr><tr><td><code>caf.databases.yaml</code></td><td>Databases</td><td>7</td><td>4</td></tr><tr><td><code>caf.governance.yaml</code></td><td>Governance (policy &amp; compliance)</td><td>7</td><td>2</td></tr><tr><td><code>caf.hybrid.yaml</code></td><td>Hybrid</td><td>6</td><td>2</td></tr><tr><td><code>caf.identity.yaml</code></td><td>Identity</td><td>7</td><td>3</td></tr><tr><td><code>caf.integration.yaml</code></td><td>Integration</td><td>6</td><td>0</td></tr><tr><td><code>caf.iot.yaml</code></td><td>IoT</td><td>13</td><td>5</td></tr><tr><td><code>caf.management.yaml</code></td><td>Management</td><td>6</td><td>1</td></tr><tr><td><code>caf.network.yaml</code></td><td>Network</td><td>7</td><td>1</td></tr><tr><td><code>caf.platformauto.yaml</code></td><td>Platform automation</td><td>6</td><td>3</td></tr><tr><td><code>caf.resourceorg.yaml</code></td><td>Resource organization</td><td>6</td><td>2</td></tr><tr><td><code>caf.security.yaml</code></td><td>Security</td><td>7</td><td>1</td></tr><tr><td><code>caf.storage.yaml</code></td><td>Storage</td><td>6</td><td>2</td></tr><tr><td><code>caf.web.yaml</code></td><td>Web</td><td>6</td><td>2</td></tr><tr><td><code>waf.cost.yaml</code></td><td>Cost optimization</td><td>6</td><td>1</td></tr><tr><td><code>waf.operational.yaml</code></td><td>Operational excellence</td><td>6</td><td>3</td></tr><tr><td><code>waf.performance.yaml</code></td><td>Performance efficiency</td><td>6</td><td>2</td></tr><tr><td><code>waf.reliability.yaml</code></td><td>Reliability</td><td>3</td><td>1</td></tr><tr><td><code>waf.security.yaml</code></td><td>Security</td><td>7</td><td>2</td></tr><tr><td><code>waf.storage.yaml</code></td><td>Storage reliability (<strong>not a pillar</strong>)</td><td>5</td><td>4</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>148</strong></td><td><strong>47 (32%)</strong></td></tr></tbody></table><h3 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/azure/well-architected/pillars" target="_blank" rel="noreferrer">WAF pillars</a> · per-pillar checklists: <a href="https://learn.microsoft.com/en-us/azure/well-architected/reliability/checklist" target="_blank" rel="noreferrer">Reliability</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/security/checklist" target="_blank" rel="noreferrer">Security</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/checklist" target="_blank" rel="noreferrer">Cost Optimization</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">Operational Excellence</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">Performance Efficiency</a></li><li><a href="https://learn.microsoft.com/en-us/azure/well-architected/service-guides/" target="_blank" rel="noreferrer">WAF service guides</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/whats-new" target="_blank" rel="noreferrer">What&#39;s new in WAF</a></li><li><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/landing-zone/design-areas" target="_blank" rel="noreferrer">Azure landing zone design areas</a> · <a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/landing-zone/tailoring-alz" target="_blank" rel="noreferrer">Tailor the ALZ architecture</a> · <a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/enterprise-scale/faq" target="_blank" rel="noreferrer">ALZ FAQ</a> · <a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/whats-new" target="_blank" rel="noreferrer">What&#39;s new in CAF</a></li><li>CAF Govern methodology: <a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/govern/build-cloud-governance-team" target="_blank" rel="noreferrer">Build a cloud governance team</a> · <a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/govern/enforce-cloud-governance-policies" target="_blank" rel="noreferrer">Enforce cloud governance policies</a></li><li><a href="https://learn.microsoft.com/en-us/assessments/21765fea-dfe6-4bc4-8bb7-db9df5a6f6c0/" target="_blank" rel="noreferrer">Azure Landing Zone Review assessment</a> · <a href="https://learn.microsoft.com/en-us/assessments/b1891add-7646-4d60-a875-32a4ab26327e" target="_blank" rel="noreferrer">Cloud Governance assessment</a></li></ul>`,158)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
